{
  "typography": {
    "caption": {
      "fontWeight": 500,
      "letterSpacing": 0.5
    },
    "detail": {
      "fontWeight": 400,
      "letterSpacing": 0.4
    },
    "body": {
      "fontWeight": 400,
      "letterSpacing": 0.25
    },
    "label": {
      "fontWeight": 500,
      "letterSpacing": 0.1
    },
    "title": {
      "fontWeight": 500,
      "letterSpacing": 0.15
    },
    "headline": {
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "display": {
      "fontWeight": 400,
      "letterSpacing": 0
    }
  },
  "dimension": {
    "size": {
      "hit": {
        "pointer": 0,
        "touch": 48
      },
      "density": {
        "pointer": {
          "pad": 16,
          "gap": 12
        },
        "touch": {
          "pad": 16,
          "gap": 12
        }
      },
      "item": {
        "pointer": {
          "inset": 0,
          "pad": 12
        },
        "touch": {
          "inset": 0,
          "pad": 12
        }
      },
      "control": {
        "pointer": {
          "padding": 8,
          "gap": 8
        },
        "touch": {
          "padding": 8,
          "gap": 8
        }
      },
      "height": {
        "pointer": {
          "sm": 24,
          "md": 32,
          "lg": 40
        },
        "touch": {
          "sm": 32,
          "md": 40,
          "lg": 56
        }
      }
    },
    "stroke": {
      "hairline": 1,
      "control": 1
    },
    "focus": {
      "style": "outline",
      "width": 3,
      "offset": 2
    },
    "icon": {
      "pointer": {
        "sm": 12,
        "md": 16,
        "lg": 20
      },
      "touch": {
        "sm": 16,
        "md": 20,
        "lg": 24
      }
    }
  },
  "controls": {
    "button": {
      "corner": {
        "sm": "full",
        "md": "full",
        "lg": "full"
      },
      "selected": {
        "face": {
          "finish": "accent"
        },
        "ink": {
          "color": "primary-foreground"
        }
      },
      "secondary": {
        "face": {
          "color": "secondary"
        },
        "ink": {
          "color": "secondary-foreground"
        },
        "edge": "none",
        "hover": {
          "finish": "hover"
        }
      },
      "outline": {
        "edge": {
          "color": "input"
        }
      },
      "destructive": {
        "edge": "none"
      },
      "shade": "none"
    },
    "badge": {
      "corner": "full"
    },
    "field": {
      "edge": {
        "sides": false,
        "color": {
          "color": "input"
        },
        "bottom": {
          "color": "muted-foreground"
        }
      },
      "corner": {
        "bottom": 0
      },
      "focus": {
        "line": true,
        "width": 2,
        "color": {
          "color": "brand"
        }
      },
      "disabled": {
        "face": "keep"
      }
    },
    "choice": {
      "size": {
        "pointer": 20,
        "touch": 20
      },
      "box": {
        "pointer": 18,
        "touch": 18
      },
      "corner": {
        "pointer": 2,
        "touch": 2
      },
      "face": "none",
      "shade": "none",
      "edge": {
        "width": 2,
        "color": {
          "color": "muted-foreground"
        },
        "disabled": {
          "color": "muted-foreground"
        }
      },
      "checked": {
        "face": {
          "color": "primary"
        }
      },
      "radio": {
        "checked": {
          "face": "none",
          "edge": {
            "color": "primary"
          }
        }
      },
      "mark": {
        "size": {
          "pointer": 10,
          "touch": 10
        },
        "hover": "none",
        "pressed": "none"
      },
      "halo": 32
    },
    "switch": {
      "track": {
        "pointer": [
          40,
          24
        ],
        "touch": [
          52,
          32
        ]
      },
      "small": {
        "track": {
          "pointer": [
            32,
            20
          ],
          "touch": [
            40,
            24
          ]
        },
        "knob": {
          "pointer": 12,
          "touch": 12
        }
      },
      "edge": {
        "off": {
          "pointer": 2,
          "touch": 2
        },
        "on": 0,
        "color": {
          "color": "input"
        }
      },
      "knob": {
        "size": {
          "pointer": 16,
          "touch": 16
        },
        "on": {
          "pointer": 20,
          "touch": 24
        },
        "hover": "same",
        "pressed": {
          "pointer": 22,
          "touch": 28
        }
      }
    },
    "slider": {
      "rail": {
        "pointer": 4,
        "touch": 4
      },
      "band": {
        "pointer": 20,
        "touch": 32
      },
      "face": {
        "color": "secondary"
      },
      "shade": "none",
      "edge": {
        "color": "none",
        "width": 0
      },
      "knob": {
        "size": {
          "pointer": 16,
          "touch": 20
        },
        "pressed": {
          "pointer": 16,
          "touch": 32
        },
        "face": {
          "color": "primary"
        },
        "edge": "none"
      },
      "mark": {
        "size": 0,
        "hover": 0,
        "pressed": 0
      },
      "brightens": true
    },
    "progress": {
      "height": 4,
      "line": 0,
      "face": {
        "color": "secondary"
      },
      "shade": "none",
      "edge": {
        "color": "none",
        "width": 0
      }
    },
    "calendar": {
      "today": {
        "face": {
          "color": "foreground",
          "alpha": 0.08
        },
        "ink": {
          "color": "foreground"
        }
      }
    },
    "spinner": {
      "opacity": 0,
      "spokes": false
    },
    "popup": {
      "corner": "control"
    },
    "tooltip": {
      "face": {
        "finish": "inverse"
      },
      "ink": {
        "finish": "inverse",
        "field": "foreground"
      },
      "edge": "none",
      "shade": "none"
    },
    "toast": {
      "action": {
        "face": "none"
      }
    },
    "list": {
      "item": {
        "highlight": {
          "color": "accent"
        },
        "edge": "none"
      }
    },
    "menubar": {
      "bar": {
        "finish": "card"
      }
    },
    "tabs": {
      "track": {
        "face": "none",
        "edge": {
          "color": "border"
        },
        "corner": "full"
      }
    },
    "well": {
      "edge": "none"
    },
    "disabled": {
      "face": {
        "finish": "disabled"
      },
      "ink": {
        "finish": "disabled",
        "field": "foreground"
      },
      "edge": {
        "color": "foreground",
        "alpha": 0.12
      }
    }
  },
  "shape": {
    "curve": "circular"
  },
  "state": {
    "press-scale": 1,
    "overlay": {
      "hover": 0.08,
      "pressed": 0.1
    },
    "pressed-opacity": 1,
    "rest-opacity": 0.38,
    "disabled": {
      "content": 0.38
    }
  },
  "motion": {
    "fast": {
      "duration": 150,
      "timingFunction": "standard"
    },
    "default": {
      "duration": 250,
      "timingFunction": "standard"
    },
    "slow": {
      "duration": 400,
      "timingFunction": "emphasized-decelerate"
    },
    "state": {
      "duration": 100,
      "timingFunction": "standard"
    }
  },
  "finishes": {
    "shared": {
      "card": {
        "background": "{card}",
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "border-color": "transparent",
        "elevation": 1
      },
      "inset": {
        "shadow": "none",
        "foreground": "{foreground}",
        "border-color": "{muted-foreground}",
        "border-bottom-color": null
      },
      "channel": {
        "background": "{inset}",
        "shadow": "none",
        "foreground": "{foreground}",
        "border-color": "{line}"
      },
      "raised": {
        "background": "{raised}",
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "border-color": "transparent",
        "border-top-color": "transparent",
        "border-bottom-color": "transparent",
        "backdropFilter": "none",
        "material": null
      },
      "plate": {
        "background": "{secondary}",
        "shadow": "none",
        "foreground": "{foreground}",
        "border-color": "transparent",
        "elevation": 0
      },
      "overlay": {
        "background": "{popover}",
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 2px 6px 2px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "border-color": "transparent",
        "backdropFilter": "none",
        "material": null,
        "elevation": 3
      },
      "modal": {
        "shadow": "0 1px 3px oklch(0 0 0 / 0.3), 0 4px 8px 3px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "border-color": "transparent",
        "elevation": 6
      },
      "inverse": {
        "background": "{inverse}",
        "shadow": "0 1px 3px oklch(0 0 0 / 0.3), 0 4px 8px 3px oklch(0 0 0 / 0.15)",
        "foreground": "{inverse-foreground}",
        "border-color": "transparent",
        "backdropFilter": "none",
        "material": null,
        "elevation": 6
      },
      "glass": {
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "border-color": "transparent",
        "backdropFilter": "none",
        "background": "{popover}",
        "material": null,
        "elevation": 3
      },
      "accent": {
        "background": "{primary}",
        "shadow": "none",
        "foreground": "{primary-foreground}",
        "border-color": "transparent",
        "border-bottom-color": "transparent",
        "pressed-opacity": 1,
        "pressed-background": null,
        "pressed-foreground": null
      },
      "fill": {
        "shadow": "none",
        "foreground": "{primary-foreground}",
        "background": "{primary}",
        "gradient": null,
        "border-color": "transparent"
      },
      "knob": {
        "shadow": "none",
        "foreground": "{foreground}",
        "background": "{knob}",
        "gradient": null,
        "border-color": "transparent",
        "checked-background": "{primary-foreground}"
      },
      "hover": {
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "background": "{raised}",
        "border-color": "transparent",
        "border-top-color": "transparent",
        "border-bottom-color": "transparent",
        "elevation": 1
      },
      "pressed": {
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "background": "{raised}",
        "border-color": "transparent",
        "elevation": 1
      },
      "disabled": {
        "background": "oklch(from {foreground} l c h / 0.12)",
        "shadow": "none",
        "foreground": "oklch(from {foreground} l c h / 0.38)",
        "border-color": "transparent"
      }
    },
    "light": {
      "modal": {
        "background": "oklch(0.93251 0.01479 312.24)"
      }
    },
    "dark": {
      "modal": {
        "background": "oklch(0.2859 0.01293 298.633)"
      }
    }
  },
  "elevation": {
    "light": {
      "sm": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
      "md": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
      "lg": "0 1px 2px oklch(0 0 0 / 0.3), 0 2px 6px 2px oklch(0 0 0 / 0.15)",
      "xl": "0 1px 3px oklch(0 0 0 / 0.3), 0 4px 8px 3px oklch(0 0 0 / 0.15)",
      "inset": null
    },
    "dark": {
      "sm": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
      "md": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
      "lg": "0 1px 2px oklch(0 0 0 / 0.3), 0 2px 6px 2px oklch(0 0 0 / 0.15)",
      "xl": "0 1px 3px oklch(0 0 0 / 0.3), 0 4px 8px 3px oklch(0 0 0 / 0.15)",
      "inset": null
    }
  }
}

{
  "$schema": "https://www.designtokens.org/schemas/2025.10/format.json",
  "$description": "Material (light appearance, pointer tier) — standalone W3C DTCG 2025.10 tokens.",
  "$extensions": {
    "dev.aning.shadcn-nsh": {
      "designMd": {
        "sharedDos": [
          "Read all colors, radii, typography, and surface finishes through theme roles (`colors.*`, `shape.*`, `font.*`, `finish.*`) rather than literals in component code.",
          "Read theme getters inside JSX render expressions or reactive effects so runtime theme switching (`selectTheme`) and light/dark appearance changes take effect on the next frame.",
          "Use `rounded(shape.<role>, inset)` for concentric nested radii inside cards, switches, and segmented controls."
        ],
        "sharedDonts": [
          "Never write color literals (`#...`, `rgb()`, `oklch()`) in component, lib, or demo-adapter code.",
          "Never store `colors.*`, `finish.*`, or `shape.*` values in module-level constants; they freeze on theme or appearance switches.",
          "Never add a finish field a role does not use: the fields of `finish.<role>` are the ones `packages/theme/finish-fields.ts` lists, and every theme states them the same way."
        ],
        "voiceOmitted": "Voice & Content Strategy is intentionally omitted: this theme defines visual tokens, surface finishes, typography metrics, and motion physics only; product copy, tone, capitalization, and terminology belong to the host application.",
        "overview": "Material 3 Expressive (`material-web` v34.0.21 / Compose Material 3 1.5.0) built from the `#6750A4` baseline with tonal surface containers, Expressive Tone 30 `on*Container` roles, state-layer overlays, and M3 duration and easing motion.",
        "elevation": "Tonal surface stepping plus Material Web Level 1–3 shadows and `material.android.elevation` (1dp/3dp/6dp), no backdrop blur, and a line only where a well or a channel states one (`inset`, `channel`): every other finish draws no edge (`border-color: transparent`).",
        "dos": [
          "Express interaction states via M3 state-layer ink overlays (`hover: 0.08`, `focus: 0.10`, `pressed: 0.10`, `dragged: 0.16`) with `state.press-scale: 1`.",
          "Use `shape.curve: \"circular\"` with top-rounded underlined fields and underlined tabs.",
          "Keep tonal and elevated containers edge-free through `border-color: transparent` in the finish, so depth comes from tonal steps and elevation; a well or channel keeps its hairline."
        ],
        "donts": [
          "Do not add backdrop blur (`backdropFilter`) or a surface edge (`border-color`) to M3 tonal surfaces.",
          "Do not replace `outline` focus rings (`3px` width, `2px` offset) with halo rings."
        ]
      }
    }
  },
  "cubicBezier": {
    "$type": "cubicBezier",
    "$description": "Named timing curves shared across themes.",
    "out-cubic": {
      "$value": [
        0.333333,
        1,
        0.666667,
        1
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.out(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "out-cubic"
        }
      }
    },
    "in-cubic": {
      "$value": [
        0.333333,
        0,
        0.666667,
        0
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.in(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-cubic"
        }
      }
    },
    "in-out-cubic": {
      "$value": [
        0.65,
        0,
        0.35,
        1
      ],
      "$description": "Cubic approximation of NSH Easing.inOut(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-out-cubic"
        }
      }
    },
    "standard": {
      "$value": [
        0.2,
        0,
        0,
        1
      ],
      "$description": "Material 3 md.sys.motion.easing.standard."
    },
    "emphasized-decelerate": {
      "$value": [
        0.05,
        0.7,
        0.1,
        1
      ],
      "$description": "Material 3 emphasized-decelerate curve."
    },
    "emphasized-accelerate": {
      "$value": [
        0.3,
        0,
        0.8,
        0.15
      ],
      "$description": "Material 3 emphasized-accelerate curve."
    },
    "decelerate": {
      "$value": [
        0,
        0,
        0,
        1
      ],
      "$description": "WinUI 3 Fast Out, Slow In curve (entering elements)."
    },
    "accelerate": {
      "$value": [
        1,
        0,
        1,
        1
      ],
      "$description": "WinUI 3 Slow Out, Fast In curve (exiting elements)."
    },
    "point-to-point": {
      "$value": [
        0.55,
        0.55,
        0,
        1
      ],
      "$description": "WinUI 3 Point-to-Point motion curve."
    }
  },
  "typography": {
    "$type": "typography",
    "$description": "Material 3 Expressive type weights; sizes follow the shared scale (ADR 0009).",
    "caption": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.caption}",
        "fontWeight": 500,
        "lineHeight": "{font.line-height.caption}",
        "letterSpacing": {
          "value": 0.5,
          "unit": "px"
        }
      },
      "$description": "Small captions and segmented counter labels."
    },
    "detail": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.detail}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.detail}",
        "letterSpacing": {
          "value": 0.4,
          "unit": "px"
        }
      },
      "$description": "Sidebar section labels, counts, and supporting metadata."
    },
    "body": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.body}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.body}",
        "letterSpacing": {
          "value": 0.25,
          "unit": "px"
        }
      },
      "$description": "Standard body copy, list rows, and dialog content."
    },
    "label": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.label}",
        "fontWeight": 500,
        "lineHeight": "{font.line-height.label}",
        "letterSpacing": {
          "value": 0.1,
          "unit": "px"
        }
      },
      "$description": "Control labels, form labels, and interactive triggers."
    },
    "title": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.title}",
        "fontWeight": 500,
        "lineHeight": "{font.line-height.title}",
        "letterSpacing": {
          "value": 0.15,
          "unit": "px"
        }
      },
      "$description": "Card and section headings."
    },
    "headline": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.headline}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.headline}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Page-level headings."
    },
    "display": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.display}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.display}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Large display numerals and hero headings."
    }
  },
  "dimension": {
    "$type": "dimension",
    "$description": "Desktop pointer layout density, control geometry, and icon sizes.",
    "stroke": {
      "$description": "Border stroke widths.",
      "hairline": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Hairline width for dividers, container edges (cards, drawers, overlays) and outlined variants."
      },
      "control": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Interactive control border width."
      }
    },
    "focus": {
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "style": "outline"
        }
      },
      "$description": "M3 focus indicator: 3px solid outline offset 2px (_md-sys-state-focus-indicator.scss).",
      "width": {
        "$value": {
          "value": 3,
          "unit": "px"
        },
        "$description": "Focus ring stroke width."
      },
      "offset": {
        "$value": {
          "value": 2,
          "unit": "px"
        },
        "$description": "2px outward focus indicator offset per M3."
      }
    },
    "radius": {
      "$type": "dimension",
      "$description": "Material 3 Expressive corner scale (Compose tokens at `ac364f3c`: 4px CornerExtraSmall control, 12px CornerMedium/CornerLarge container, 28px CornerExtraLarge modal; capsule buttons via `shape.corners.button: \"full\"`).",
      "control": {
        "$value": {
          "value": 4,
          "unit": "px"
        },
        "$description": "Corner radius for in-page controls, fields, rows, chips, badges, wells, color areas, and kbd."
      },
      "container": {
        "$value": {
          "value": 12,
          "unit": "px"
        },
        "$description": "Corner radius for cards, menus, popovers, tooltips, list panels, toasts, and frames."
      },
      "modal": {
        "$value": {
          "value": 28,
          "unit": "px"
        },
        "$description": "Corner radius for dialogs, sheets, and drawers."
      }
    },
    "size": {
      "$description": "Ergonomic sizing scales for pointer input.",
      "hit": {
        "$value": {
          "value": 0,
          "unit": "px"
        },
        "$description": "Minimum hit target size (0 disables padding expansion)."
      },
      "density": {
        "$description": "Page-level padding and gap.",
        "pad": {
          "$value": {
            "value": 16,
            "unit": "px"
          }
        },
        "gap": {
          "$value": {
            "value": 12,
            "unit": "px"
          }
        }
      },
      "item": {
        "$description": "Material 3 menu rows: the fill spans the menu's width (inset 0; a DropdownMenuItem takes no horizontal margin) and the text sits 12dp in (DropdownMenuItemHorizontalPadding, androidx compose material3 Menu.kt).",
